using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Staff.Characters;using Staff.Shared;using Object=UnityEngine.Object;
namespace Staff.Traversal.Editor {
[InitializeOnLoad] public static class TangentVerification {
 const string Key="Staff.TangentVerify";static double start;static bool running;
 static TangentVerification(){EditorApplication.update+=Tick;}
 public static void Run(){TangentSetup.Run();File.WriteAllText("Library/TangentReview/verification.txt","");foreach(var path in new[]{"Assets/Scenes/STAFF_City_Reference.unity","Assets/Scenes/STAFF_Subway_Reference.unity","Assets/Scenes/SampleScene.unity"}){if(!File.Exists(path))continue;var s=EditorSceneManager.OpenScene(path);var a=Object.FindFirstObjectByType<TangentTraversal>();Require(a&&a.castClip&&a.flightClip&&a.equationTexture,"Shared prefab references in "+s.name);}EditorSceneManager.OpenScene(TangentSetup.City);SessionState.SetBool(Key,true);EditorApplication.isPlaying=true;}
 static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying||EditorApplication.isCompiling)return;if(start==0){start=EditorApplication.timeSinceStartup;return;}if(running||EditorApplication.timeSinceStartup-start<5)return;running=true;try{Check();SessionState.SetBool(Key,false);EditorApplication.Exit(0);}catch(Exception e){File.AppendAllText("Library/TangentReview/verification.txt","FAIL "+e);Debug.LogException(e);SessionState.SetBool(Key,false);EditorApplication.Exit(1);}}
 static void Require(bool ok,string msg){if(!ok)throw new Exception(msg);File.AppendAllText("Library/TangentReview/verification.txt","PASS "+msg+"\n");}
 static AdventurePlayer player;static TangentTraversal ability;static CharacterController cc;
 static void Place(Vector3 p){ability.Cancel();cc.enabled=false;player.transform.position=p;cc.enabled=true;Physics.SyncTransforms();}
 static bool AimAt(Vector3 p){var source=player.transform.position+Vector3.up;return ability.Aim(new Ray(source,(p-source).normalized));}
 static void Advance(int count){for(int i=0;i<count;i++){player.Simulate(default,.016f);ability.SendMessage("LateUpdate");Physics.SyncTransforms();}}
 static void Check(){
  player=Object.FindFirstObjectByType<AdventurePlayer>();ability=player.GetComponent<TangentTraversal>();cc=player.GetComponent<CharacterController>();var cam=Camera.main;float cityScale=player.gameObject.scene.GetRootGameObjects().Single(g=>g.name=="Environment").transform.lossyScale.x;
  var buildings=Object.FindObjectsByType<TangentSurface>(FindObjectsSortMode.None);Require(buildings.Length>=20,"City buildings opt into traversal");
  var west=buildings.Single(b=>b.name=="Sage Corner Bookshop").GetComponentsInChildren<Collider>().First(c=>c.name=="Main plaster mass").bounds;
  var east=buildings.Single(b=>b.name=="Ochre Bookshop").GetComponentsInChildren<Collider>().First(c=>c.name=="Main plaster mass").bounds;
  Place(new Vector3(0,.3f,4)*cityScale);Require(AimAt(new Vector3(west.max.x,7*cityScale,4*cityScale)),"Aim at first building");Require(ability.Launch(),"Launch first tangent");Advance(12);var line=player.transform.parent.GetComponentsInChildren<LineRenderer>().Single(x=>x.name=="Tangent");Require(line.positionCount==2&&line.sharedMaterial.GetColor("_BaseColor")==Color.white,"Tangent is one white straight segment with exactly two vertices");var cameraController=cam.GetComponent<AdventureCamera>();cameraController.Simulate(.1f);Require(cameraController.WafflusRig.VirtualCamera.m_Lens.FieldOfView>60,"Shared camera widens FOV during traversal");Capture("city-flight",cam);Advance(150);Require(ability.State==TangentTraversal.Phase.Wall&&ability.CompletedHops==1,"First building arrival and wall hold");Capture("city-wall",cam);
  Require(AimAt(new Vector3(east.min.x,8*cityScale,4*cityScale)),"Aim from wall at opposite building");Require(ability.Launch(),"Launch chained tangent without landing");Advance(80);Require(ability.State==TangentTraversal.Phase.Wall&&ability.CompletedHops==2,"Second building arrival: continuous wall-to-wall traversal");Capture("city-chain",cam);
  ability.Cancel();Advance(30);Require(player.VerticalVelocity<0,"Cancel restores gravity and locomotion");
  Place(new Vector3(0,.3f,4)*cityScale);Require(!ability.Aim(new Ray(player.transform.position+Vector3.up,Vector3.up)),"Sky cannot be targeted");Require(!ability.Launch(),"Invalid target cannot launch");
  var blocker=GameObject.CreatePrimitive(PrimitiveType.Cube);blocker.name="Verification obstacle";blocker.transform.position=new Vector3(-3,4,4)*cityScale;blocker.transform.localScale=new Vector3(.25f,9,6)*cityScale;Physics.SyncTransforms();Require(!AimAt(new Vector3(west.max.x,7*cityScale,4*cityScale)),"Occluder blocks target acquisition");Object.DestroyImmediate(blocker);
  Place(new Vector3(0,.3f,4)*cityScale);Require(AimAt(new Vector3(west.max.x,7*cityScale,4*cityScale))&&ability.Launch(),"Launch before newly introduced obstacle");blocker=GameObject.CreatePrimitive(PrimitiveType.Cube);blocker.transform.position=new Vector3(-3,4,4)*cityScale;blocker.transform.localScale=new Vector3(.25f,9,6)*cityScale;Physics.SyncTransforms();Advance(90);Require(ability.State==TangentTraversal.Phase.Idle&&player.transform.position.x>-3*cityScale,"Swept capsule stops at obstacle during high-speed flight");Object.DestroyImmediate(blocker);
  Place(new Vector3(0,.3f,4)*cityScale);Require(AimAt(new Vector3(west.max.x,7*cityScale,4*cityScale))&&ability.Launch(),"Launch before reset");Advance(15);player.Respawn();Require(ability.State==TangentTraversal.Phase.Idle&&player.Animator.runtimeAnimatorController,"Reset cleans up playable and restores controller");
  var roof=buildings.Single(b=>b.name=="Ochre Bookshop").GetComponentsInChildren<Collider>().First(c=>c.name=="Tangent Roof Collision").bounds;Place(roof.center+Vector3.up*6);Require(AimAt(roof.center)&&ability.Launch(),"Acquire rooftop from above");Advance(80);Require(ability.CompletedHops==3&&!ability.OwnsMovement,"Rooftop landing returns movement control");
  Place(new Vector3(0,.3f,4)*cityScale);Require(AimAt(new Vector3(west.max.x,7*cityScale,4*cityScale))&&ability.Launch(),"Acquire wall for timeout check");Advance(280);Require(!ability.OwnsMovement&&player.VerticalVelocity<0,"Wall hold expires and gravity resumes");
  Place(new Vector3(0,.3f,4)*cityScale);Require(AimAt(new Vector3(west.max.x,7*cityScale,4*cityScale))&&ability.Launch(),"Acquire for blocked input check");player.InputBlocked=true;Advance(1);Require(!ability.OwnsMovement,"Blocked input cancels traversal");player.InputBlocked=false;
  var switcher=player.GetComponent<CharacterSwitcher>();switcher.Select(0);Place(new Vector3(0,.3f,4)*cityScale);Require(AimAt(new Vector3(west.max.x,7*cityScale,4*cityScale))&&ability.Launch(),"Shared ability also launches on alternate character");Advance(20);switcher.Cycle();Require(ability.State==TangentTraversal.Phase.Idle&&player.Animator.runtimeAnimatorController,"Character switch safely cancels traversal");
 }
 static void Capture(string name,Camera cam){ability.SendMessage("LateUpdate");var hips=player.Animator.isHuman?player.Animator.GetBoneTransform(HumanBodyBones.Hips):player.transform;File.AppendAllText("Library/TangentReview/verification.txt",name+" root="+player.transform.position+" hips="+hips.position+"\n");var originalPosition=cam.transform.position;var originalRotation=cam.transform.rotation;cam.transform.position=player.transform.position+new Vector3(player.transform.position.x>0?-4:4,2,-6);cam.transform.LookAt(player.transform.position+Vector3.up);var rt=new RenderTexture(1280,720,24);var old=RenderTexture.active;var target=cam.targetTexture;try{cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var t=new Texture2D(1280,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1280,720),0,0);t.Apply();File.WriteAllBytes("Library/TangentReview/"+name+".png",t.EncodeToPNG());Object.DestroyImmediate(t);}finally{cam.targetTexture=target;RenderTexture.active=old;Object.DestroyImmediate(rt);cam.transform.SetPositionAndRotation(originalPosition,originalRotation);}}
}
}
